  timeout_sec  = 10

  backend {
    group = google_compute_instance_group.default.self_link
  }
}

resource "google_compute_instance_group" "default" {
  project      = var.project
  name         = "instance-group"
  zone         = var.zone
  instances    = [google_compute_instance.default.self_link]
}

