resource "aws_security_group" "ecs_sg" {
  name        = "ecs-sg"
  description = "ECS Security Group configuration"
  vpc_id      = aws_vpc.ecs_vpc.id

  ingress {
    description = "EC2 to ECS"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-sg"
  }
}

# Create an IAM role for the ECS task
resource "aws_iam_role" "ecs_task_role" {
  name        = "ecs-task-role"
  description = "ECS Task Role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}

# Create an IAM policy for the ECS task
resource "aws_iam_policy" "ecs_task_policy" {
  name        = "ecs-task-policy"
  description = "ECS Task Policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "arn:aws:logs:*:*:*"
        Effect    = "Allow"
      }
    ]
  })
}

# Attach the IAM policy to the IAM role
resource "aws_iam_role_policy_attachment" "ecs_task_policy_attachment" {
  role       = aws_iam_role.ecs_task_role.name
  policy_arn = aws_iam_policy.ecs_task_policy.arn
}

# Create an ECS cluster
resource "aws_ecs_cluster" "ecs_cluster" {
  name = "ecs-cluster"
}

# Create an ECS task definition
resource "aws_ecs_task_definition" "ecs_task_definition" {
  family                = "ecs-task-definition"
  cpu                    = var.task_cpu
  memory                = var.task_memory
  network_mode          = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  execution_role_arn    = aws_iam_role.ecs_task_role.arn
  container_definitions = jsonencode([
    {
      name      = "ecs-container"
      image      = var.container_image
      cpu        = var.container_cpu
      memory    = var.container_memory
      essential = true
      portMappings = [
        {
          containerPort = var.container_port
          hostPort      = var.container_port
          protocol      = "tcp"
        }
      ]
    }
  ])
}

# Create an ALB
resource "aws_alb" "ecs_alb" {
  name            = "ecs-alb"
  subnets         = [aws_subnet.ecs_subnet.id]
  security_groups = [aws_security_group.ecs_sg.id]

  tags = {
    Name = "ecs-alb"
  }
}

# Create an ALB target group
resource "aws_alb_target_group" "ecs_target_group" {
  name     = "ecs-target-group"
  port     = var.container_port
  protocol = "HTTP"
  vpc_id   = aws_vpc.ecs_vpc.id

  health_check {
    healthy_threshold   = 3
    unhealthy_threshold = 10
    timeout             = 5
    interval            = 10
    path                = "/"
    port                = var.container_port
  }
}

# Create an ALB listener
resource "aws_alb_listener" "ecs_listener" {
  load_balancer_arn = aws_alb.ecs_alb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    target_group_arn = aws_alb_target_group.ecs_target_group.arn
    type             = "forward"
  }
}

# Create an ECS service
resource "aws_ecs_service" "ecs_service" {
  name            = "ecs-service"
  cluster         = aws_ecs_cluster.ecs_cluster.name
  task_definition = aws_ecs_task_definition.ecs_task_definition.arn
  desired_count   = var.desired_count
  launch_type      = "FARGATE"

  network_configuration {
    subnets          = [aws_subnet.ecs_subnet.id]
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = "ENABLED"
  }

  load_balancer {
    target_group_arn = aws_alb_target_group.ecs_target_group.arn
    container_name   = "ecs-container"
    container_port   = var.container_port
  }

  depends_on = [aws_alb_listener.ecs_listener]
}

